/**
 * Exo Seidel-2D driver: mirrors PolyBench/C seidel-2d.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"

/* Include the Exo-generated kernel header. */
#include "generated/seidel-2d/seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline Seidel-2D stencil: in-place Gauss–Seidel style 3x3 average.
@proc
def kernel_seidel_2d_impl(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We only touch interior points A[1:n-1, 1:n-1]
    assert n > 2

    for t in seq(0, tsteps):
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                A[i, j] = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                ) / 9.0

# ---------------------------------------------------------------------------
# Scheduling: cache-friendly 2D tiling plus inner unrolling over j.
#
# - divide_loop preserves the original lexicographic (i, j) order, so the
#   Gauss–Seidel update pattern (using already-updated north and west
#   neighbors within a time-step) is unchanged.
# - Tiling improves spatial locality in both i and j.
# - Unrolling the innermost j-sub-tile reduces loop overhead and exposes
#   small contiguous chunks that the C compiler can keep in registers.
# ---------------------------------------------------------------------------

kernel_seidel_2d = kernel_seidel_2d_impl

# Tile the i and j loops. The "guard" tail strategy keeps semantics correct
# when (n-2) is not a multiple of the tile size.
tile_i = 32
tile_j = 32

kernel_seidel_2d = divide_loop(kernel_seidel_2d, "i", tile_i, ("io", "ii"), tail="guard")
kernel_seidel_2d = divide_loop(kernel_seidel_2d, "j", tile_j, ("jo", "ji"), tail="guard")

# Further split the innermost j-tile into a tiny loop and fully unroll it.
unroll_j = 4
kernel_seidel_2d = divide_loop(kernel_seidel_2d, "ji", unroll_j, ("jii", "jiii"), tail="guard")
kernel_seidel_2d = unroll_loop(kernel_seidel_2d, kernel_seidel_2d.find_loop("jiii"))

# Clean up the IR and give the final scheduled kernel the expected name.
kernel_seidel_2d = simplify(kernel_seidel_2d)
kernel_seidel_2d = rename(kernel_seidel_2d, "kernel_seidel_2d")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
