from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We need at least a 3x3 grid to apply the 9-point stencil.
    assert n > 2

    # Precompute the reciprocal of 9 once per kernel invocation.
    inv9: DATA_TYPE
    inv9 = 1.0 / 9.0

    # Gauss–Seidel time stepping.
    for t in seq(0, tsteps):
        # Sweep rows from top to bottom.
        for i in seq(1, n - 1):
            # Sliding 3x3 window along the j dimension for the three rows
            # [i-1, i, i+1]. This reduces memory traffic substantially:
            # for each new column we only load three new elements instead
            # of nine, reusing six values from the previous column.

            up0: DATA_TYPE
            up1: DATA_TYPE
            up2: DATA_TYPE
            mid0: DATA_TYPE
            mid1: DATA_TYPE
            mid2: DATA_TYPE
            dn0: DATA_TYPE
            dn1: DATA_TYPE
            dn2: DATA_TYPE

            # Initialize the window for j = 1. This gives us the
            # neighborhood {j-1, j, j+1} = {0, 1, 2}.
            up0 = A[i - 1, 0]
            up1 = A[i - 1, 1]
            up2 = A[i - 1, 2]

            mid0 = A[i, 0]
            mid1 = A[i, 1]
            mid2 = A[i, 2]

            dn0 = A[i + 1, 0]
            dn1 = A[i + 1, 1]
            dn2 = A[i + 1, 2]

            # Inner sweep over columns, excluding boundary columns.
            for j in seq(1, n - 1):
                # Compute the new value for A[i, j] using the current
                # 3x3 window. At this point the window holds:
                #   up*  -> A[i-1, j-1..j+1]
                #   mid* -> A[i,   j-1..j+1] (with mid0 possibly new)
                #   dn*  -> A[i+1, j-1..j+1]
                A[i, j] = (
                    up0 + up1 + up2 +
                    mid0 + mid1 + mid2 +
                    dn0 + dn1 + dn2
                ) * inv9

                # Slide the window one column to the right for j+1, unless
                # we are at the last inner column j = n-2. For the last
                # iteration we already have j+1 = n-1 in the window.
                if j < n - 2:
                    # Row i-1: shift right, bring in A[i-1, j+2].
                    up0 = up1
                    up1 = up2
                    up2 = A[i - 1, j + 2]

                    # Row i: the just-written center A[i, j] becomes the
                    # left neighbor for the next iteration.
                    mid0 = A[i, j]
                    mid1 = mid2
                    mid2 = A[i, j + 2]

                    # Row i+1: shift right, bring in A[i+1, j+2].
                    dn0 = dn1
                    dn1 = dn2
                    dn2 = A[i + 1, j + 2]


# Apply a simple IR simplification pass to clean up expressions.
kernel_seidel_2d = simplify(kernel_seidel_2d)
EXO END
